Index: .config/tmux/plugins/tpm/scripts/helpers/tmux_echo_functions.sh
===================================================================
--- .config/tmux/plugins/tpm/scripts/helpers/tmux_echo_functions.sh	
+++ .config/tmux/plugins/tpm/scripts/helpers/tmux_echo_functions.sh	
@@ -0,0 +1,28 @@
+_has_emacs_mode_keys() {
+	$(tmux show -gw mode-keys | grep -q emacs)
+}
+
+tmux_echo() {
+	local message="$1"
+	tmux run-shell "echo '$message'"
+}
+
+echo_ok() {
+	tmux_echo "$*"
+}
+
+echo_err() {
+	tmux_echo "$*"
+}
+
+end_message() {
+	if _has_emacs_mode_keys; then
+		local continue_key="ESCAPE"
+	else
+		local continue_key="ENTER"
+	fi
+	tmux_echo ""
+	tmux_echo "TMUX environment reloaded."
+	tmux_echo ""
+	tmux_echo "Done, press $continue_key to continue."
+}

Index: .config/tmux/plugins/tpm/tests/expect_successful_multiple_plugins_download
===================================================================
--- .config/tmux/plugins/tpm/tests/expect_successful_multiple_plugins_download	
+++ .config/tmux/plugins/tpm/tests/expect_successful_multiple_plugins_download	
@@ -0,0 +1,44 @@
+#!/usr/bin/env expect
+
+# disables script output
+log_user 0
+
+spawn tmux
+
+# Waiting for tmux to attach. If this is not done, next command, `send` will
+# not work properly.
+sleep 1
+
+# this is tmux prefix + I
+send "I"
+
+# cloning might take a while
+set timeout 15
+
+expect_after {
+  timeout { exit 1 }
+}
+
+expect {
+  "Installing \"tmux-example-plugin\""
+}
+
+expect {
+  "\"tmux-example-plugin\" download success"
+}
+
+expect {
+  "Installing \"tmux-copycat\""
+}
+
+expect {
+  "\"tmux-copycat\" download success"
+}
+
+expect {
+  "Done, press ENTER to continue." {
+    exit 0
+  }
+}
+
+exit 1

